     QDBusReply<QDBusObjectPath> reply = co_await NetworkManager::addAndActivateConnection(map, device, specificObject);
     if (!alive) {
         co_return;
@@ -513,6 +525,29 @@ QCoro::Task<> Handler::deactivateConnectionInternal(const QString &_connection,
