+QCoro::Task<> Handler::deactivateLimitedConnection(const QString &device, const QString &newConnectionUuid)
+{
+    const NetworkManager::Connectivity connectivity = NetworkManager::connectivity();
+    if (connectivity != NetworkManager::Limited && connectivity != NetworkManager::Portal) {
+        co_return;
+    }
+
+    NetworkManager::Device::Ptr dev = NetworkManager::findNetworkInterface(device);
+    if (!dev) {
+        co_return;
+    }
+
+    NetworkManager::ActiveConnection::Ptr active = dev->activeConnection();
+    NetworkManager::ActiveConnection::Ptr primary = NetworkManager::primaryConnection();
+    if (!active || !primary || active->path() != primary->path() || active->uuid() == newConnectionUuid) {
+        co_return;
+    }
+
+    // Unlike being replaced by the new activation, an explicit deactivation makes NetworkManager
+    // stop autoconnecting to the limited connection until the user activates it again
+    co_await NetworkManager::deactivateConnection(active->path());
+}
